CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "Administradores" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Usuario" character varying(50) NOT NULL,
        "HashContrasena" text NOT NULL,
        CONSTRAINT "PK_Administradores" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "Categorias" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(100) NOT NULL,
        CONSTRAINT "PK_Categorias" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "Clientes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(150) NOT NULL,
        "Correo" character varying(150) NOT NULL,
        "Telefono" character varying(20),
        "Direccion" character varying(300),
        CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "Productos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(150) NOT NULL,
        "Descripcion" character varying(1000),
        "Precio" numeric(10,2) NOT NULL,
        "Stock" integer NOT NULL,
        "CategoriaId" integer NOT NULL,
        "ImagenUrl" character varying(500),
        "Activo" boolean NOT NULL DEFAULT TRUE,
        "FechaCreacion" timestamp with time zone NOT NULL DEFAULT (now()),
        CONSTRAINT "PK_Productos" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Productos_Precio" CHECK ("Precio" > 0),
        CONSTRAINT "CK_Productos_Stock" CHECK ("Stock" >= 0),
        CONSTRAINT "FK_Productos_Categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES "Categorias" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "Ordenes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ClienteId" integer NOT NULL,
        "Fecha" timestamp with time zone NOT NULL DEFAULT (now()),
        "Total" numeric(10,2) NOT NULL,
        "Estado" character varying(20) NOT NULL,
        CONSTRAINT "PK_Ordenes" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Ordenes_Total" CHECK ("Total" >= 0),
        CONSTRAINT "FK_Ordenes_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE TABLE "DetallesOrden" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OrdenId" integer NOT NULL,
        "ProductoId" integer NOT NULL,
        "Cantidad" integer NOT NULL,
        "PrecioUnitario" numeric(10,2) NOT NULL,
        "Subtotal" numeric(10,2) NOT NULL,
        CONSTRAINT "PK_DetallesOrden" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_DetallesOrden_Cantidad" CHECK ("Cantidad" > 0),
        CONSTRAINT "CK_DetallesOrden_PrecioUnitario" CHECK ("PrecioUnitario" > 0),
        CONSTRAINT "CK_DetallesOrden_Subtotal" CHECK ("Subtotal" >= 0),
        CONSTRAINT "FK_DetallesOrden_Ordenes_OrdenId" FOREIGN KEY ("OrdenId") REFERENCES "Ordenes" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_DetallesOrden_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE UNIQUE INDEX "IX_Administradores_Usuario" ON "Administradores" ("Usuario");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE UNIQUE INDEX "IX_Categorias_Nombre" ON "Categorias" ("Nombre");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE UNIQUE INDEX "IX_DetallesOrden_OrdenId_ProductoId" ON "DetallesOrden" ("OrdenId", "ProductoId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE INDEX "IX_DetallesOrden_ProductoId" ON "DetallesOrden" ("ProductoId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE INDEX "IX_Ordenes_ClienteId" ON "Ordenes" ("ClienteId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    CREATE INDEX "IX_Productos_CategoriaId" ON "Productos" ("CategoriaId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030031710_Inicial') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261030031710_Inicial', '10.0.14');
    END IF;
END $EF$;
COMMIT;

